test('queued remittance actual155to156 preserves old files jobs remittances and broker helper identities',async()=>{
 const f=await fixture({throughSchema:155});try{const h=await remittanceFixture(f);assert.equal((await f.request(h.remittancePath,h.remittanceInput)).response.status,201);const old=await f.request('reports/jobs',{reportId:'payroll.settlements',parameters:{on:'2026-02-15'}});assert.equal(old.response.status,202);const file=await f.request('reports/payroll/settlements/export?on=2026-02-15');assert.equal(file.response.status,200);assert.equal((await f.pg.query<{ok:boolean}>('SELECT public.report_result_context_valid($1,$2::jsonb) ok',['payroll.remittances',JSON.stringify({kind:'payroll_remittance',postingIds:[h.posting.id]})])).rows[0].ok,false);
 // Generate prior-schema bytes through its real read API and persist through
 // its real broker. Do not run the newer schema-gated worker before upgrade.
 await f.pg.exec('BEGIN;SET LOCAL ROLE kavosh_automation_worker');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);const lease=(await f.pg.query<{lease_token:string}>('SELECT * FROM public.claim_report_job($1)',[[f.a]])).rows[0];assert.ok(lease);assert.equal((await f.pg.query<{ok:boolean}>("SELECT public.finish_report_job($1,$2,'succeeded',NULL,$3,'prior-settlements.csv',$4::jsonb) ok",[old.body.data.id,lease.lease_token,file.body,JSON.stringify({kind:'payroll_settlement',postingIds:[h.posting.id]})])).rows[0].ok,true);await f.pg.exec('COMMIT');}catch(error){await f.pg.exec('ROLLBACK');throw error;}assert.equal((await f.request('reports/jobs',{reportId:'finance.trial-balance',parameters:{through:'2026-02-15'}})).response.status,202);const snapshot=async()=>({jobs:(await f.pg.query('SELECT * FROM public.report_jobs ORDER BY id')).rows,files:(await f.pg.query('SELECT * FROM public.report_job_results ORDER BY job_id')).rows,remittances:(await f.pg.query('SELECT * FROM public.payrun_remittances ORDER BY id')).rows,journals:(await f.pg.query('SELECT * FROM public.finance_journals ORDER BY id')).rows,audits:(await f.pg.query('SELECT * FROM public.audit_events ORDER BY id')).rows,helpers:(await f.pg.query("SELECT oid,proowner,proacl FROM pg_proc WHERE oid IN('public.report_result_context_valid(text,jsonb)'::regprocedure,'public.report_job_guard()'::regprocedure,'public.report_job_preset_guard()'::regprocedure) ORDER BY oid")).rows}),before=await snapshot();await f.pg.exec(await readFile(new URL('../db/migrations/156_payroll_remittance_jobs.sql',import.meta.url),'utf8'));assert.deepEqual(await snapshot(),before);assert.equal((await f.pg.query('SELECT public.schema_revision() revision')).rows[0].revision,156);assert.equal((await f.request('reports/jobs/'+old.body.data.id+'/download')).body,file.body);await upgradeToCurrent(f.pg);assert.equal((await background(f)).outcome,'succeeded');const q=await f.request('reports/jobs',{reportId:'payroll.remittances',parameters:{on:'2026-02-15'}});assert.equal(q.response.status,202);assert.equal((await background(f)).outcome,'succeeded');assert.equal((await f.request('reports/jobs/'+q.body.data.id+'/download')).response.status,200);}finally{await f.pg.close();}
});
