async function hourlyEvidence(f:Fixture){
 const caps=['session-reports.view','session-reports.record','session-reports.edit','attendance.view','rosters.view','session-time.view','staff.view','files.view','session-time.record','session-evidence.view','session-evidence.edit','session-evidence.override'];for(const role of [f.staffRole,f.managerRole])for(const cap of caps)await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow') ON CONFLICT DO NOTHING",[f.a,role,cap]);
 const session=(await f.request('classes/'+f.c.id+'/sessions')).body.data[0];assert.equal((await f.request('sessions/'+session.id+'/change',{expectedVersion:1,reason:'Synthetic actual class',change:{kind:'reschedule',start:'2026-01-05T10:00',end:'2026-01-05T11:00'}})).response.status,200);const timeInput={expectedVersion:0,assignmentId:f.assignment.id,assignmentVersion:1,sessionVersion:2,startsAt:'2026-01-05T15:00:00Z',endsAt:'2026-01-05T16:00:00Z',reason:'PRIVATE actual delivered time'},t=await f.request('sessions/'+session.id+'/my-time',timeInput,'staff');assert.equal(t.response.status,201);
 const h=await f.request('payroll/hourly-accruals',{...f.base,personId:f.input.personId,from:'2026-01-05',through:'2026-01-05',timeZone:'UTC',currencyId:f.currency.id,basis:'actual',reference:'READINESS-HOURS',earningReview:'PRIVATE accepted work',roundingReview:'PRIVATE retained actual time'});assert.equal(h.response.status,201,JSON.stringify(h.body));const run=await made(f,{earnings:[{kind:'hourly',sourceId:h.body.data.id,allocationId:f.engagement.id}]}),path='payroll/payruns/'+run.id+'/readiness',read=(as='master')=>f.request(path,undefined,as);
 async function attendance(){assert.equal((await f.request('sessions/'+session.id+'/attendance/change',{expectedVersion:0,sessionVersion:2,entries:[],reason:'PRIVATE exact no-enrollment roster'})).response.status,200);}
 async function report(){const file=await f.made('files',{anchor:{kind:'class',id:f.c.id},domain:'general',name:'PRIVATE report image.jpg',claimedMimeType:'image/jpeg',expectedBytes:1234,expectedSha256:'a'.repeat(64)});const document={title:'PRIVATE robotics report',locale:'en',blocks:[{id:randomUUID(),kind:'text',text:'PRIVATE shared report body'},{id:randomUUID(),kind:'media',fileId:file.id,fileVersion:1,mediaKind:'image',caption:'PRIVATE media caption'}]};assert.equal((await f.request('sessions/'+session.id+'/report',{expectedVersion:0,sessionVersion:2,assignmentId:f.assignment.id,assignmentVersion:1,document,reason:'PRIVATE shared session report'},'staff')).response.status,201);return file;}
 const review=(patch:Record<string,unknown>={})=>f.request('sessions/'+session.id+'/evidence-review',{expectedVersion:0,decision:'accepted',waiveReport:false,waiveMedia:false,reason:'PRIVATE upper human input review',...patch});
 return {session,timeInput,time:t.body.data,hourly:h.body.data,run,path,read,attendance,report,review};
}

